```java
@Service
public class EurostatService {
    private final EurostatRepository repository;
    public List<EurostatSeries> listAll() { return repository.findAll().stream().sorted(Comparator.comparing(EurostatSeries::period).reversed()).toList(); }
    public Optional<EurostatSeries> findByPeriod(String period) { return repository.findByPeriod(period); }
    public boolean existsByPeriod(String period) { return repository.existsByPeriod(period); }
    public SeriesSummary summary() {
        List<EurostatSeries> all = listAll();
        if (all.isEmpty()) return new SeriesSummary(0, null, null, null, null, 0);
        EurostatSeries latest = all.get(0); // newest
        EurostatSeries earliest = all.get(all.size()-1);
        double avg = all.stream().mapToDouble(EurostatSeries::unemploymentRatePct).average().orElse(0);
        return new SeriesSummary(all.size(), latest.period(), latest.unemploymentRatePct(), earliest.period(), earliest.unemploymentRatePct(), avg);
    }
    public PageResult<EurostatSeries> page(int page, int size, String year) {
        List<EurostatSeries> all = listAll();
        List<EurostatSeries> filtered = year == null || year.isBlank() ? all : all.stream().filter(s -> s.period().startsWith(year + "-")).toList();
        int safeSize = Math.max(1, Math.min(size, 100));
        int totalPages = filtered.isEmpty() ? 0 : (int) Math.ceil((double) filtered.size() / safeSize);
        int safePage = totalPages == 0 ? 0 : Math.max(0, Math.min(page, totalPages - 1));
        int from = safePage * safeSize;
        int to = Math.min(from + safeSize, filtered.size());
        List<EurostatSeries> items = from >= filtered.size() ? List.of() : filtered.subList(from, to);
        return new PageResult<>(items, safePage, safeSize, filtered.size(), totalPages, safePage > 0, safePage + 1 < totalPages);
    }
    public List<String> years() { return listAll().stream().map(s -> s.period().substring(0,4)).distinct().sorted(Comparator.reverseOrder()).toList(); }
    public int ping() { return repository.ping(); }
}
```
