        if (bindingResult.hasErrors()) { model.addAttribute("isEdit", false); return "notes/form"; }
        try { SeriesNote note = noteService.create(form); redirectAttributes.addFlashAttribute("message", "Note created for " + note.period() + "."); return "redirect:/notes"; }
