        model.addAttribute("form", SeriesNoteForm.from(note));
        model.addAttribute("isEdit", true);
        model.addAttribute("noteId", id);
        return "notes/form";
    }
    @PostMapping("/{id}")
    public String update(@PathVariable long id, @Valid @ModelAttribute("form") SeriesNoteForm form, BindingResult bindingResult, Model model, RedirectAttributes redirectAttributes) {
        if (bindingResult.hasErrors()) { model.addAttribute("isEdit", true); model.addAttribute("noteId", id); return "notes/form"; }
        try { noteService.update(id, form); redirectAttributes.addFlashAttribute("message", "Note updated."); return "redirect:/notes"; }
